function useConsumable(itemId) {
  if (countItem(itemId) <= 0) { showMsg('None left!'); return; }
  if (itemId==='bread')      { player.stamina=Math.min(player.maxStamina,player.stamina+25); showMsg('🍞 Ate bread — +25 stamina.'); }
  if (itemId==='potion')     { player.hp=Math.min(player.maxHp,player.hp+40); showMsg('🧪 Drank potion — +40 HP.'); }
  if (itemId==='bigPotion')  { player.hp=Math.min(player.maxHp,player.hp+80); showMsg('🫙 Big Potion — +80 HP!'); }
  removeItem(itemId, 1);
}
