function fillPenTrough(pen) {
  const feedItems = ['carrot','corn','pumpkin','glowroot','tomato','dustwheat','sunblossom'];
  const feedVal = { carrot:8, corn:15, pumpkin:20, glowroot:25, tomato:10, dustwheat:12, sunblossom:30 };
