    const penType = penAnimals[0]?.type;
    const icons = { chicken:'🐔', sheep:'🐑', cow:'🐄' };
    const dailyCost = penAnimals.reduce((s,a) => s + ANIMAL_DEFS[a.type].feedCost, 0);
