    if (!p.tilled || !p.crop) continue;
    if (!p.wateredToday) {
      if (getDifficultyConfig().cropWilt !== false) {
        const wasOk = !p.wilted;
        p.wilted = true;
        if (wasOk && settings.wiltNotify) showMsg('🥀 Some crops wilted overnight — water them before next dawn!');
      }
    } else {
      p.wilted = false;
    }
    p.wateredToday = false;
    p.watered = false;
    const [lx,ly] = key.split(',').map(Number);
    setT(lx, ly, TL.FARM_TILLED);
  }
  inventory.water = inventory.waterCap;
  if (player._autoWater) {
    for (const key in plots) {
      const p = plots[key];
      if (p && p.tilled && p.crop && !p.harvestReady) {
        p.watered = p.wateredToday = true; p.wilted = false;
        const [lx,ly] = key.split(',').map(Number);
        setT(lx, ly, TL.FARM_WATERED);
      }
    }
    showMsg('🚿 Sprinklers fired! All crops auto-watered.');
  }
  refreshInvUI();
  checkWeeklyBill();
  updateDebtClock();   // ← keep debt clock fresh each dawn
  dSound('dawn');      // ← dawn fanfare
  if (settings.autoSave) saveGame(true);
}
