```javascript
function drawFogTile(sx, sy, seed) {
  // Base — deep dark, slightly blue-grey
  ctx.fillStyle = 'rgba(18,17,24,0.97)';
  ctx.fillRect(sx, sy, T, T);

  // Clip to tile
  ctx.save();
  ctx.beginPath(); ctx.rect(sx, sy, T, T); ctx.clip();

  // LCG seeded noise — stable per tile, no per-frame flicker
  let s = seed >>> 0;
  const rng = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 0xffffffff; };

  // Cloud puffs — soft ellipses stacked for depth
  // Layer 1 — large base puffs (darkest)
  const puffs1 = 2 + Math.floor(rng() * 2);
  for (let i = 0; i < puffs1; i++) {
    const cx2 = sx + rng() * T;
    const cy2 = sy + rng() * T;
    const rx  = 8 + rng() * 10;
    const ry  = 5 + rng() * 7;
    ctx.fillStyle = `rgba(38,36,50,${0.6 + rng() * 0.25})`;
    ctx.beginPath(); ctx.ellipse(cx2, cy2, rx, ry, rng()*Math.PI, 0, Math.PI*2); ctx.fill();
  }
  // Layer 2 — mid puffs (lighter grey)
  const puffs2 = 2 + Math.floor(rng() * 3);
  for (let i = 0; i < puffs2; i++) {
    const cx2 = sx + rng() * T;
    const cy2 = sy + rng() * T;
    const rx  = 5 + rng() * 8;
    const ry  = 3 + rng() * 5;
    ctx.fillStyle = `rgba(58,55,72,${0.5 + rng() * 0.3})`;
    ctx.beginPath(); ctx.ellipse(cx2, cy2, rx, ry, rng()*Math.PI, 0, Math.PI*2); ctx.fill();
  }
  // Layer 3 — highlight wisps on top-left edges
  const wisps = 1 + Math.floor(rng() * 2);
  for (let i = 0; i < wisps; i++) {
    const cx2 = sx + rng() * T * 0.6;  // biased left/top for light source
    const cy2 = sy + rng() * T * 0.6;
    const rx  = 3 + rng() * 6;
    const ry  = 2 + rng() * 4;
    ctx.fillStyle = `rgba(80,76,100,${0.2 + rng() * 0.2})`;
    ctx.beginPath(); ctx.ellipse(cx2, cy2, rx, ry, rng()*Math.PI, 0, Math.PI*2); ctx.fill();
  }

  ctx.restore();
}
