function drawClockDecorations(ctx, cols) {
  /* Large clock face — center of map, row 8-9 area */
  const cx = 24 * NES.TILE;
  const cy = 8  * NES.TILE;
  const R  = 20;

  ctx.fillStyle = ZONE_PAL[ZONE_ID.CLOCK].solidBase;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = ZONE_PAL[ZONE_ID.CLOCK].solidTop;
  /* Clock ring */
  for (let a = 0; a < 12; a++) {
    const ang = (a / 12) * Math.PI * 2 - Math.PI / 2;
    const mx  = cx + Math.cos(ang) * (R - 4);
    const my  = cy + Math.sin(ang) * (R - 4);
    ctx.fillRect((mx - 1) | 0, (my - 1) | 0, 2, 2);
  }

  /* Clock hands — stopped */
  ctx.fillStyle = PAL.STONE_HIGH;
  /* Hour hand points to "3" (right — the hour player died) */
  ctx.fillRect(cx, cy - 1, R - 6, 2);
  /* Minute hand points to "12" (up) */
  ctx.fillRect(cx - 1, cy - (R - 4), 2, R - 4);
  /* Center pin */
  ctx.fillStyle = PAL.PALE_GOLD;
  ctx.fillRect(cx - 1, cy - 1, 2, 2);

  /* Gear decorations — baked in as circular pixel art */
  [[7 * NES.TILE, 8 * NES.TILE], [36 * NES.TILE, 9 * NES.TILE]].forEach(([gx, gy]) => {
    ctx.fillStyle = ZONE_PAL[ZONE_ID.CLOCK].solidTop;
    const gr = 10;
    for (let tooth = 0; tooth < 8; tooth++) {
      const a = (tooth / 8) * Math.PI * 2;
      ctx.fillRect(
        (gx + Math.cos(a) * gr - 2) | 0,
        (gy + Math.sin(a) * gr - 2) | 0,
        4, 4
      );
    }
    ctx.fillStyle = ZONE_PAL[ZONE_ID.CLOCK].solidBase;
    ctx.beginPath();
    ctx.arc(gx, gy, gr - 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = PAL.GOLD;
    ctx.fillRect(gx - 1, gy - 1, 2, 2);
  });
}
