function drawThroneDecorations(ctx, cols) {
  const T     = NES.TILE;
  const ROWS  = 20;
  const zpal  = ZONE_PAL[ZONE_ID.THRONE];
  const mapH  = ROWS * T;

  /* ── Floor-to-ceiling pillars — six of them, evenly spaced ──
     These give the "impossibly tall" feeling of a cathedral.
     Each pillar: 4px wide, full map height, with carved notches. */
  [6, 12, 20, 28, 34, 42].forEach(col => {
    const px = col * T + 6;
    /* Pillar shaft */
    ctx.fillStyle = zpal.solidBase;
    ctx.fillRect(px, 0, 4, mapH);
    /* Top capital */
    ctx.fillStyle = zpal.solidTop;
    ctx.fillRect(px - 2, T, 8, 3);
    /* Carved notches every 32px (every 2 rows) */
    for (let y = T * 3; y < mapH - T * 2; y += T * 2) {
      ctx.fillStyle = zpal.solidShad;
      ctx.fillRect(px, y, 4, 2);
    }
    /* Base plinth */
    ctx.fillStyle = zpal.solidTop;
    ctx.fillRect(px - 2, mapH - T * 2, 8, 3);
  });

  /* ── Curse rune chains — diagonal lines connecting pillar to pillar ──
     Pixel-art stipple: every other pixel along a diagonal path. */
  ctx.fillStyle = PAL.CLOAK_MID;
  for (let step = 0; step < 180; step++) {
    const x = ((step * 3) % (cols * T)) | 0;
    const y = (step * 2 + T * 4) | 0;
    if (y < mapH - T * 2) ctx.fillRect(x, y, 1, 1);
  }

  /* ── Throne silhouette — back wall centre, row 0-4 ── */
  const tx = 22 * T;
  /* Throne base */
  ctx.fillStyle = zpal.solidBase;
  ctx.fillRect(tx, T, T * 4, T * 3);
  /* Throne back */
  ctx.fillStyle = zpal.solidTop;
  ctx.fillRect(tx + T, 0, T * 2, T * 2);
  /* Throne armrests */
  ctx.fillStyle = zpal.solidBase;
  ctx.fillRect(tx, T + 4, T, T);
  ctx.fillRect(tx + T * 3, T + 4, T, T);
  /* Crown spikes on throne */
  ctx.fillStyle = PAL.PALE_GOLD;
  [tx + 2, tx + T, tx + T * 2, tx + T * 3 - 2].forEach(sx => {
    ctx.fillRect(sx, 0, 3, T - 4);
    ctx.fillRect(sx + 1, 0 - 2, 1, 2);  /* spike tip */
