function drawEntryDecorations(ctx, cols) {
  const T   = NES.TILE;
  const zpal = ZONE_PAL[ZONE_ID.ENTRY];

  /* ── Background arched windows — cast shadow patterns ──
     NES Castlevania has tall arched windows in castle walls.
     We bake these into the static canvas as dark recesses. */
  [8, 28, 48].forEach(col => {
    const wx = col * T;
    const wy = T;   /* Row 1 top */
    /* Window recess — dark inset rectangle in wall */
    ctx.fillStyle = '#0a0608';
    ctx.fillRect(wx + 2, wy + 2, T*2 - 4, T*4 - 2);
    /* Pointed arch crown */
    ctx.fillRect(wx + 4, wy,     T*2 - 8, 3);
    ctx.fillRect(wx + 6, wy - 2, T*2 - 12, 2);
    /* Window frame */
    ctx.fillStyle = zpal.solidTop;
    ctx.fillRect(wx + 1, wy + 1, 2, T*4);   /* left frame */
    ctx.fillRect(wx + T*2 - 3, wy + 1, 2, T*4);  /* right frame */
    ctx.fillRect(wx + 2, wy, T*2 - 4, 2);   /* arch lintel */
    /* Cross pane */
    ctx.fillStyle = '#2c1808';
    ctx.fillRect(wx + T - 1, wy + 2, 2, T*4 - 4);   /* vertical */
    ctx.fillRect(wx + 3, wy + T*2,   T*2 - 6, 2);   /* horizontal */
  });

  /* ── Chandeliers — three, detailed with wrought iron brackets ── */
  [Math.floor(cols * 0.2), Math.floor(cols * 0.5), Math.floor(cols * 0.8)].forEach(col => {
    const cx = col * T + 8;
    const cy = T;

    /* Bracket — angled arm from ceiling */
    ctx.fillStyle = zpal.solidShad;
    ctx.fillRect(cx - 2, cy,     4, 2);   /* ceiling mount */
    ctx.fillStyle = PAL.STONE_MID;
    ctx.fillRect(cx - 1, cy + 2, 2, 4);  /* chain 1 */
    ctx.fillRect(cx - 1, cy + 7, 2, 4);  /* chain 2 */
    ctx.fillRect(cx - 1, cy + 12,2, 3);  /* chain 3 */

    /* Crosspiece — black iron with highlight */
    ctx.fillStyle = '#1a0c04';
    ctx.fillRect(cx - 12, cy + 15, 24, 4);
    ctx.fillStyle = zpal.solidTop;
    ctx.fillRect(cx - 12, cy + 15, 24, 1);   /* top sheen */
    /* End scrolls */
    ctx.fillStyle = '#1a0c04';
    ctx.fillRect(cx - 14, cy + 16, 3, 3);
    ctx.fillRect(cx + 11, cy + 16, 3, 3);

    /* Four candles with drip wax */
    [-8, -3, 3, 8].forEach(dx => {
      const cx2 = cx + dx;
      /* Wax drip — yellow-white */
      ctx.fillStyle = '#f0e0b0';
      ctx.fillRect(cx2, cy + 18, 2, 3);
      ctx.fillRect(cx2 - 1, cy + 19, 1, 2);  /* drip left */
      /* Candle body — cream white */
      ctx.fillStyle = PAL.LIGHTGRAY;
      ctx.fillRect(cx2, cy + 20, 2, 5);
      ctx.fillStyle = '#f8f0e0';
      ctx.fillRect(cx2, cy + 20, 1, 5);  /* highlight */
      /* Flame — three pixels: dark base, red, gold tip */
      ctx.fillStyle = PAL.FIRE_RED;
      ctx.fillRect(cx2, cy + 17, 2, 2);
      ctx.fillStyle = PAL.PALE_GOLD;
      ctx.fillRect(cx2, cy + 16, 2, 1);
      ctx.fillStyle = PAL.WHITE;
      ctx.fillRect(cx2, cy + 16, 1, 1);
    });

    /* Light pool on floor beneath chandelier — subtle warm tone */
    ctx.fillStyle = '#2c1808';
    ctx.fillRect(cx - 14, 9*T, 28, 1);
  });

  /* ── Cobwebs — pixel-art radial webs in corners ── */
  const webColor = '#3c2818';
  ctx.fillStyle = webColor;
  /* Upper-left corner: rays from (T, T) */
  for (let r = 4; r <= 28; r += 4) {
    ctx.fillRect(T,         T + r,     r,     1);   /* horiz strand */
    ctx.fillRect(T + r,     T,         1,     r);   /* vert strand  */
    /* Diagonal cross-strand */
    if (r >= 8) {
      const d = (r >> 1);
      ctx.fillRect(T + d,   T + d, 1, 1);           /* node */
    }
  }
  /* Arc strands (approximated with fillRects at angles) */
  [[4,20],[8,16],[12,12],[16,8],[20,4]].forEach(([ax,ay]) => {
    ctx.fillRect(T + ax, T + ay, 1, 1);
  });

  /* Upper-right corner */
  const rEdge = (cols - 2) * T;
  ctx.fillStyle = webColor;
  for (let r = 4; r <= 28; r += 4) {
    ctx.fillRect(rEdge - r,      T + r, r, 1);
    ctx.fillRect(rEdge,          T,     1, r);
    if (r >= 8) {
      const d = (r >> 1);
      ctx.fillRect(rEdge - d, T + d, 1, 1);
    }
  }
  [[4,20],[8,16],[12,12],[16,8],[20,4]].forEach(([ax,ay]) => {
    ctx.fillRect(rEdge - ax, T + ay, 1, 1);
  });

  /* ── Wall torch sconces — lit torches between windows ── */
  [18, 38, 58].forEach(col => {
    const tx2 = col * T + 4;
    const ty2 = T * 3;
    /* Sconce bracket */
    ctx.fillStyle = '#1a0c04';
    ctx.fillRect(tx2, ty2 + 2, 6, 2);
    ctx.fillRect(tx2 + 2, ty2, 2, 4);
    /* Torch handle */
    ctx.fillStyle = '#4c2808';
    ctx.fillRect(tx2 + 2, ty2 + 4, 2, 6);
    /* Flame — animated would be handled at runtime, bake static ember */
    ctx.fillStyle = PAL.FIRE_RED;
    ctx.fillRect(tx2 + 1, ty2,     4, 2);
    ctx.fillStyle = PAL.PALE_GOLD;
    ctx.fillRect(tx2 + 2, ty2 - 1, 2, 2);
    /* Light halo — two-pixel warm tint around flame */
    ctx.fillStyle = '#2c1408';
    ctx.fillRect(tx2,     ty2 - 2, 6, 1);
    ctx.fillRect(tx2 - 1, ty2,     8, 2);
  });

  /* ── Floor flagstones — baked crack patterns on floor row ── */
  ctx.fillStyle = '#1c0e06';
  [5, 14, 22, 31, 40, 50].forEach(col => {
    const fx = col * T;
    const fy = 9 * T;
    ctx.fillRect(fx, fy + 6, T, 1);   /* horizontal crack */
    ctx.fillRect(fx + T - 1, fy, 1, T - 2);  /* vertical joint */
