  const tx0 = Math.max(0,          ( p.x              / NES.TILE) | 0);
  const tx1 = Math.min(md.cols-1, ((p.x + p.w - 1)   / NES.TILE) | 0);
  const ty0 = Math.max(0,          ( p.y              / NES.TILE) | 0);
