        /* If the hit killed the player, stop scanning — a door tile later in
           the same AABB could call transitionZone and override STATE.DEAD. */
        if (G.state !== STATE.PLAYING) return;
      }

      /* Weapon pickup */
      if (id === T.WEAPON) {
        if (!p.weapons.includes('bone_whip')) {
